import json

# Check if CLS predictions were present in the input data
for fname in ['data/re_repair_v2/re_repair_instances_with_cls.jsonl', 'data/re_repair_v2/re_repair_instances_final.jsonl']:
    try:
        data = [json.loads(l) for l in open(f'/home/sonny/eval_results/{fname}')]
    except:
        try:
            data = [json.loads(l) for l in open(f'/home/sonny/{fname}')]
        except:
            print(f'{fname}: NOT FOUND')
            continue
    print(f'{fname}: {len(data)} records')
    has_cls = sum(1 for d in data if d.get('cls_per_test') and len(d['cls_per_test']) > 0)
    print(f'  with cls_per_test: {has_cls}/{len(data)}')
    if data:
        print(f'  keys: {list(data[0].keys())}')
        cls = data[0].get('cls_per_test', {})
        print(f'  first cls_per_test: {len(cls)} tests, sample={dict(list(cls.items())[:2]) if cls else \"empty\"}')
"
